async function reconcileManagedHostRun(
  paths: ManagedHostRunPaths,
  now: number,
  processGroupOps: ManagedHostRunProcessGroupOps = DEFAULT_PROCESS_GROUP_OPS,
): Promise<void> {
  await withManagedReconcileLock(paths, async () => {
    await reconcileManagedHostRunUnlocked(paths, now, processGroupOps);
  });
}

export async function getManagedHostRunStatus(args: {
  root: string;
  runId: string;
  afterGeneration?: number;
  waitMs?: number;
  /** Internal handler-smoke seam; production omits this and retains the 30s cap. */
  maxWaitMs?: number;
  /** Internal process-smoke clock seam; production always uses Date.now. */
  now?: () => number;
  /** Process-boundary seam used by executable cleanup-fact tests; production uses OS process groups. */
  processGroupOps?: ManagedHostRunProcessGroupOps;
}): Promise<ManagedHostRunStatusResult> {
  const paths = pathsFor(args.root, args.runId);
  if (!existsSync(paths.spec)) throw new Error(`managed host run not found: ${args.runId}`);
  const waitMs = Math.min(
    boundedManagedHostRunStatusWaitMs(args.waitMs),
    boundedManagedHostRunStatusWaitMs(args.maxWaitMs ?? MANAGED_HOST_RUN_STATUS_WAIT_MAX_MS),
  );
  let run = projectionFor(paths);
  const baseline = typeof args.afterGeneration === 'number' ? args.afterGeneration : run.generation;
  const now = args.now ?? Date.now;
  const deadline = now() + waitMs;
  while (true) {
    await reconcileManagedHostRun(paths, now(), args.processGroupOps);
    run = projectionFor(paths);
    const changed = run.generation !== baseline || run.terminal !== null;
    if (changed || now() >= deadline || waitMs === 0) {
      return {
        schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
        changed,
        run,
        receipt: run.terminal ? managedHostRunReceipt(args.root, args.runId) : null,
      };
    }
    await sleep(Math.min(50, Math.max(1, deadline - now())));
  }
}

export function boundedManagedHostRunStatusWaitMs(waitMs: number | undefined): number {
  return boundedPositiveMs(waitMs, 0, MANAGED_HOST_RUN_STATUS_WAIT_MAX_MS);
}

export async function cancelManagedHostRun(args: {
  root: string;
  runId: string;
  reason?: string;
}): Promise<ManagedHostRunProjection> {
  const paths = pathsFor(args.root, args.runId);
  if (!existsSync(paths.spec)) throw new Error(`managed host run not found: ${args.runId}`);
  if (!readTerminal(paths)) ensureCancelRequest(paths, args.runId, args.reason ?? 'operator_cancelled', Date.now());
  await reconcileManagedHostRun(paths, Date.now());
  return projectionFor(paths);
}

export function readManagedHostRunOutput(args: {
  root: string;
  runId: string;
  afterSequence?: number;
}): ManagedHostRunOutputResult {
  const paths = pathsFor(args.root, args.runId);
  if (!existsSync(paths.spec)) throw new Error(`managed host run not found: ${args.runId}`);
  const terminalBeforeRead = readTerminal(paths);
  if (terminalBeforeRead) assertSealedManagedHostRunArtifacts(paths, terminalBeforeRead);
  const after = Math.max(0, Math.floor(args.afterSequence ?? 0));
  const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
  const retained = existsSync(paths.output)
    ? readBoundedUtf8(paths.output, MANAGED_HOST_RUN_OUTPUT_RETENTION_MAX_BYTES)
    : { text: '', truncated: false };
  const completeText = retained.truncated && !retained.text.endsWith('\n')
    ? retained.text.slice(0, Math.max(0, retained.text.lastIndexOf('\n') + 1))
    : retained.text;
  const allFrames = completeText
      .split('\n')
      .filter(Boolean)
      .flatMap(line => {
        try { return [JSON.parse(line) as ManagedHostRunOutputFrame]; } catch { return []; }
      })
      .filter(frame => frame.sequence > after)
    ;
  const frames = allFrames.slice(0, MANAGED_HOST_RUN_OUTPUT_READ_MAX_FRAMES);
  const hasMore = allFrames.length > frames.length;
  const nextSequence = frames.length > 0
    ? frames[frames.length - 1]!.sequence
    : snapshot.outputTruncated
      ? Math.max(after, snapshot.outputSequence)
      : after;
  const terminalAfterRead = readTerminal(paths);
  if (terminalAfterRead) assertSealedManagedHostRunArtifacts(paths, terminalAfterRead);
  return {
    schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
    runId: args.runId,
    frames,
    nextSequence,
    hasMore,
    truncated: (snapshot.outputTruncated ?? false) || retained.truncated,
  };
}

export function readManagedHostRunResult(root: string, runId: string): HostRunResult | null {
  const paths = pathsFor(root, runId);
  return existsSync(paths.result) ? readJson<HostRunResult>(paths.result) : null;
}

export function readManagedHostRunBinding(root: string, runId: string): ManagedHostRunBindingProjection {
  const paths = pathsFor(root, runId);
  // B-137a:F-127 — same archive-backed fallback managedHostRunReceipt already
  // has. Terminal-retention GC archives the receipt and then deletes the run
  // directory, so without this the spec/owner reads below throw ENOENT and
  // verifyManagedReviewEvidence fails closed on evidence that was legitimately
  // imported while the run still existed. Verified empirically: after
  // removeManagedHostRunRuntime the pre-fix reader threw ENOENT.
  if (!existsSync(paths.spec)) {
    const archivePath = managedHostRunReceiptArchivePath(root, runId);
    if (existsSync(archivePath)) {
      const archive = readJson<ManagedHostRunReceiptArchive>(archivePath);
      if (archive.schemaVersion !== 'lattice.managed_host_run_receipt_archive.v1' || archive.runId !== runId) {
        throw new Error(`managed host run ${runId}: archived binding is corrupt`);
      }
      if (archive.binding && archive.binding.runId === runId) return archive.binding;
      // Pre-F-127 archive: no binding was captured, so fail closed exactly as
      // before rather than fabricating one.
      throw new Error(
        `managed host run ${runId}: run directory was reclaimed by terminal retention and the archive predates `
        + 'binding capture, so the evidence binding cannot be reconstructed',
      );
    }
  }
  const spec = readJson<ManagedHostRunSpec>(paths.spec);
  const owner = readJson<ManagedHostRunOwner>(paths.owner);
  return {
    runId: spec.runId,
    host: spec.host,
    storyId: spec.storyId,
    phase: spec.phase,
    agentType: spec.agentType,
    reviewRunId: spec.reviewRunId,
    lane: spec.lane,
    cwd: spec.cwd,
    deadlineAt: spec.deadlineAt,
    timeoutMs: spec.timeoutMs,
    projectRootHash: spec.projectRootHash,
    profile: spec.profile,
    promptDigest: owner.promptDigest,
    reviewBinding: spec.reviewBinding ?? null,
  };
}

/** Resolve the immutable Story subject used by the CLI ownership gate. */
export function managedHostRunStoryIdForOwnership(root: string, runId: string): string | null {
  const paths = pathsFor(root, runId);
  if (!existsSync(paths.spec) || !existsSync(paths.owner)) return null;
  const specText = readFileSync(paths.spec, 'utf8');
  const spec = JSON.parse(specText) as ManagedHostRunSpec;
  const owner = readJson<ManagedHostRunOwner>(paths.owner);
  if (spec.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
    || owner.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
    || spec.runId !== runId
    || owner.runId !== runId
    || owner.specDigest !== sha256(specText)) {
    throw new Error(`managed host run ${runId}: immutable ownership subject binding mismatch`);
  }
  return typeof spec.storyId === 'string' && spec.storyId.trim().length > 0 ? spec.storyId.trim() : null;
}

type ManagedReviewFinalProposalInput = Omit<ManagedReviewEvidenceProposal, 'schemaVersion' | 'runId' | 'authoredAt'>;

function readValidManagedReviewEvidenceProposal(
  root: string,
  runId: string,
  spec: ManagedHostRunSpec,
): ManagedReviewEvidenceProposal | null {
  try {
    const proposal = readManagedReviewEvidenceProposal(root, runId);
    if (!proposal
      || proposal.schemaVersion !== 'lattice.managed_review_evidence_proposal.v1'
      || proposal.runId !== runId
      || proposal.storyId !== spec.storyId
      || proposal.providerAgent !== spec.agentType
      || proposal.lane !== spec.lane
      || proposal.reviewRunId !== spec.reviewRunId
      || !Number.isFinite(Date.parse(proposal.authoredAt))) {
      return null;
    }
    if (proposal.conclusion === 'pass') {
      if (typeof proposal.note !== 'string' || proposal.note.trim().length < 10
        || (proposal.findings !== undefined && (!Array.isArray(proposal.findings) || proposal.findings.length > 0))) {
        return null;
      }
    } else if (proposal.conclusion === 'findings') {
      if (typeof proposal.note === 'string' && proposal.note.trim().length > 0
        || !Array.isArray(proposal.findings)
        || proposal.findings.length === 0
        || !proposal.findings.every(isStrictManagedReviewFindingProposal)) {
        return null;
      }
    } else {
      return null;
    }
    normalizeReviewerReadManifest(proposal.readManifest);
    if (proposal.readLog !== undefined) normalizeReviewerReadLogEvidence(proposal.readLog);
    if (proposal.readDiagnostics !== undefined) normalizeReviewerReadDiagnostics(proposal.readDiagnostics);
    return proposal;
  } catch {
    return null;
  }
}

function parseManagedReviewFinalProposal(result: HostRunResult): ManagedReviewFinalProposalInput {
  if (result.finalAssistantResultTruncated) {
    throw new Error('managed_review_final_result_oversize');
  }
  if (result.finalAssistantResultCount > 1) {
    throw new Error('managed_review_final_result_multiple');
  }
  if (result.finalAssistantResultCount !== 1 || result.finalAssistantResult === null) {
    throw new Error('managed_review_final_result_missing');
  }
  const classification = classifyManagedReviewFinalEnvelope(result.finalAssistantResult);
  if (classification.kind !== 'valid') throw new Error('managed_review_final_result_malformed');
  const envelope = classification.envelope;
  const conclusion = envelope.conclusion;
  return {
    storyId: envelope.storyId,
    providerAgent: envelope.providerAgent,
    lane: envelope.lane,
    reviewRunId: envelope.reviewRunId,
    conclusion,
    ...(conclusion === 'pass' ? { note: envelope.note as string | undefined } : {
      findings: envelope.findings as ManagedReviewEvidenceFindingProposal[] | undefined,
    }),
    readManifest: envelope.readManifest as ReviewerReadManifest,
    ...(envelope.readLog !== undefined ? { readLog: envelope.readLog as ReviewerReadLogEvidence } : {}),
    ...(envelope.readDiagnostics !== undefined ? { readDiagnostics: envelope.readDiagnostics as ReviewerReadDiagnostic[] } : {}),
  };
}

export function writeManagedReviewEvidenceProposal(args: {
  root: string;
  runId: string;
  proposal: Omit<ManagedReviewEvidenceProposal, 'schemaVersion' | 'runId' | 'authoredAt'>;
  environment?: NodeJS.ProcessEnv;
  providerInvocationPid?: number;
  providerInvocationAttestation?: ManagedReviewProposalInvocationAttestation;
}): ManagedReviewEvidenceProposal {
  // Compatibility ingress is provider-authored input too. Keep it under the
  // same bounded final-envelope ceiling as the canonical adapter path before
  // any filesystem or authority side effect.
  if (Buffer.byteLength(canonicalJson(args.proposal), 'utf8') > HOST_RUN_FINAL_ASSISTANT_RESULT_CAP) {
    throw new Error(`managed_review_proposal_set: proposal exceeds ${HOST_RUN_FINAL_ASSISTANT_RESULT_CAP} byte managed final envelope cap`);
  }
  const paths = pathsFor(args.root, args.runId);
  const spec = readJson<ManagedHostRunSpec>(paths.spec);
  const owner = readJson<ManagedHostRunOwner>(paths.owner);
  const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
  const environment = args.environment ?? process.env;
  if (args.providerInvocationPid === undefined
    && args.providerInvocationAttestation === undefined
    && environment.LATTICE_MANAGED_HOST_RUN_ID !== args.runId) {
    throw new Error('managed_review_proposal_set: active managed-run capability is missing or mismatched');
  }
  if (readTerminal(paths) || snapshot.state !== 'running') {
    throw new Error('managed_review_proposal_set: proposal is accepted only while the managed provider run is active');
  }
  if (spec.profile !== 'managed_reviewer' || !spec.reviewBinding) {
    throw new Error('managed_review_proposal_set: run is not a formal managed_reviewer execution');
  }
  if (!spec.storyId || !spec.reviewRunId || !spec.lane) {
    throw new Error('managed_review_proposal_set: managed reviewer run is not bound to storyId/reviewRunId/lane');
  }
  const environmentAuthorized = (
    environment.LATTICE_MANAGED_REVIEW_PROPOSAL_CAPABILITY === undefined
      ? false
      : sha256(environment.LATTICE_MANAGED_REVIEW_PROPOSAL_CAPABILITY) === owner.capabilityDigest
        && environment.LATTICE_AGENT === spec.agentType
  );
  const providerInvocationAuthorized = args.providerInvocationPid !== undefined
    && providerInvocationMatches(paths, {
      storyId: args.proposal.storyId,
      providerAgent: args.proposal.providerAgent,
      lane: args.proposal.lane,
      reviewRunId: args.proposal.reviewRunId,
    }, args.providerInvocationPid);
  const descriptorInvocationAuthorized = args.providerInvocationAttestation !== undefined
    && verifyManagedReviewProposalInvocationAttestation(paths, {
      storyId: args.proposal.storyId,
      providerAgent: args.proposal.providerAgent,
      lane: args.proposal.lane,
      reviewRunId: args.proposal.reviewRunId,
    }, args.providerInvocationAttestation);
  if (!environmentAuthorized && !providerInvocationAuthorized && !descriptorInvocationAuthorized) {
    throw new Error('managed_review_proposal_set: provider proposal capability or agent identity is missing or mismatched');
  }
  if (
    args.proposal.storyId !== spec.storyId
    || args.proposal.reviewRunId !== spec.reviewRunId
    || args.proposal.lane !== spec.lane
    || args.proposal.providerAgent !== spec.agentType
  ) {
    throw new Error('managed_review_proposal_set: proposal provenance does not match the sealed managed run spec');
  }
  const conclusion = args.proposal.conclusion;
  const findings = args.proposal.findings ?? [];
  const note = args.proposal.note?.trim() ?? '';
  if (conclusion === 'pass') {
    if (note.length < 10 || findings.length > 0) {
      throw new Error('managed_review_proposal_set: pass requires note >= 10 chars and no findings');
    }
  } else if (conclusion === 'findings') {
    // The provider-owned final envelope allows a non-empty explanatory note.
    // It is diagnostic-only and deliberately omitted from the immutable
    // findings proposal below, never promoted to formal finding evidence.
    // Reject whitespace-only notes rather than silently normalizing a malformed
    // envelope into a valid proposal.
    if (findings.length === 0 || (args.proposal.note !== undefined && note.length === 0)) {
      throw new Error('managed_review_proposal_set: findings conclusion requires at least one finding and an optional non-empty diagnostic note');
    }
  } else {
    throw new Error('managed_review_proposal_set: conclusion must be pass or findings');
  }
  const normalizedFindings = findings.map((finding, index) => {
    if (!isStrictManagedReviewFindingProposal(finding)) {
      throw new Error(`managed_review_proposal_set: findings[${index}] must match the strict managed finding schema`);
    }
    return {
      ...finding,
      desc: finding.desc.trim(),
      ...(finding.files ? { files: [...new Set(finding.files.map(value => value.trim()).filter(Boolean))].sort() } : {}),
    };
  });
  const proposal: ManagedReviewEvidenceProposal = {
    schemaVersion: 'lattice.managed_review_evidence_proposal.v1',
    runId: args.runId,
    storyId: spec.storyId,
    providerAgent: spec.agentType,
    lane: spec.lane,
    reviewRunId: spec.reviewRunId,
    authoredAt: new Date().toISOString(),
    conclusion,
    ...(conclusion === 'pass' ? { note } : { findings: normalizedFindings }),
    readManifest: normalizeReviewerReadManifest(args.proposal.readManifest),
    ...(args.proposal.readLog ? { readLog: normalizeReviewerReadLogEvidence(args.proposal.readLog) } : {}),
    ...(args.proposal.readDiagnostics ? { readDiagnostics: normalizeReviewerReadDiagnostics(args.proposal.readDiagnostics) } : {}),
  };
  withTerminalAuthorityLock(paths, () => {
    if (readTerminal(paths)) {
      throw new Error('managed_review_proposal_set: proposal is accepted only while the managed provider run is active');
    }
    if (!writeExclusive(paths.evidenceProposal, proposal)) {
      throw new Error('managed_review_proposal_set: this run already has an immutable evidence proposal');
    }
    appendFileSync(paths.events, `${canonicalJson({
      schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
      runId: args.runId,
      at: proposal.authoredAt,
      type: 'review_evidence_proposed',
      detail: { conclusion, proposalDigest: digestFile(paths.evidenceProposal) },
    })}\n`, { encoding: 'utf8', mode: 0o600 });
  });
  return proposal;
}

export function readManagedReviewEvidenceProposal(root: string, runId: string): ManagedReviewEvidenceProposal | null {
  const paths = pathsFor(root, runId);
  if (existsSync(paths.evidenceProposal)) {
    return readJson<ManagedReviewEvidenceProposal>(paths.evidenceProposal);
  }
  // B-137a:F-127 — archive fallback for a run whose directory was reclaimed by
  // terminal-retention GC. The archived body is only accepted when it re-digests
  // to the SEALED receipt's evidenceProposalDigest, so a tampered or swapped
  // archive is rejected instead of trusted; a missing spec.json distinguishes a
  // genuinely reclaimed run from a merely absent proposal on a live run.
  if (!existsSync(paths.spec)) {
    const archivePath = managedHostRunReceiptArchivePath(root, runId);
    if (existsSync(archivePath)) {
      const archive = readJson<ManagedHostRunReceiptArchive>(archivePath);
      if (archive.schemaVersion !== 'lattice.managed_host_run_receipt_archive.v1' || archive.runId !== runId) {
        throw new Error(`managed host run ${runId}: archived proposal is corrupt`);
      }
      const archivedText = archive.evidenceProposalText ?? null;
      if (archivedText === null) return null;
      const expected = archive.receipt.evidenceProposalDigest;
      if (expected === null || sha256(archivedText) !== expected) {
        throw new Error(
          `managed host run ${runId}: archived proposal does not match the sealed receipt digest`,
        );
      }
      return JSON.parse(archivedText) as ManagedReviewEvidenceProposal;
    }
  }
  return null;
}

function importSealMatchesLiveContract(runId: string, bindingText: string, sealText: string): boolean {
  try {
    const seal = JSON.parse(sealText) as Record<string, unknown>;
    return seal.schemaVersion === 'lattice.managed_review_evidence_binding_seal.v1'
      && seal.runId === runId
      && seal.bindingDigest === sha256(bindingText);
  } catch {
    return false;
  }
}

/**
 * B-137a:F-127 — the import-seal pair for a run, archive-backed so an imported
 * evidence record stays verifiable after terminal-retention GC. Returns the raw
 * texts (the caller compares them exactly as it would the on-disk files) or null
 * when neither the live files nor an archive carrying them exist. An archived
 * pair is admitted only after the binding re-digests to evidenceBindingDigest
 * and the seal's schemaVersion, runId, and bindingDigest match the live path.
 */
export function readManagedReviewImportSeal(
  root: string,
  runId: string,
): { bindingText: string; sealText: string } | null {
  const paths = pathsFor(root, runId);
  if (existsSync(paths.evidenceBinding) && existsSync(paths.evidenceBindingSeal)) {
    return {
      bindingText: readFileSync(paths.evidenceBinding, 'utf8'),
      sealText: readFileSync(paths.evidenceBindingSeal, 'utf8'),
    };
  }
  if (!existsSync(paths.spec)) {
    const archivePath = managedHostRunReceiptArchivePath(root, runId);
    if (existsSync(archivePath)) {
      const archive = readJson<ManagedHostRunReceiptArchive>(archivePath);
      if (archive.schemaVersion !== 'lattice.managed_host_run_receipt_archive.v1' || archive.runId !== runId) {
        throw new Error(`managed host run ${runId}: archived import seal is corrupt`);
      }
      const bindingText = archive.evidenceBindingText ?? null;
      const sealText = archive.evidenceBindingSealText ?? null;
      if (bindingText === null || sealText === null) return null;
      const expected = archive.evidenceBindingDigest;
      if (expected === null || sha256(bindingText) !== expected) {
        throw new Error(
          `managed host run ${runId}: archived import seal does not match its recorded digest`,
        );
      }
      if (!importSealMatchesLiveContract(runId, bindingText, sealText)) {
        throw new Error(
          `managed host run ${runId}: archived import seal schema, runId, or bindingDigest is invalid`,
        );
      }
      return { bindingText, sealText };
    }
  }
  return null;
}

export function managedHostRunReceipt(root: string, runId: string): ManagedHostRunReceipt {
  const paths = pathsFor(root, runId);
  const terminal = readTerminal(paths);
  if (!terminal) {
    const archivePath = managedHostRunReceiptArchivePath(root, runId);
    if (existsSync(archivePath)) {
      const archive = readJson<ManagedHostRunReceiptArchive>(archivePath);
      const { receiptId, ...receiptPayload } = archive.receipt;
      if (archive.schemaVersion !== 'lattice.managed_host_run_receipt_archive.v1'
        || archive.runId !== runId
        || archive.receipt.runId !== runId
        || receiptId !== sha256(canonicalJson(receiptPayload))) {
        throw new Error(`managed host run ${runId}: archived terminal receipt is corrupt`);
      }
      return archive.receipt;
    }
    throw new Error(`managed host run ${runId}: terminal receipt is not available`);
  }
  assertSealedManagedHostRunArtifacts(paths, terminal);
  return receiptPayloadFor(paths, terminal);
}

export function writeManagedHostRunEvidenceBinding(root: string, runId: string, value: unknown): void {
  const paths = pathsFor(root, runId);
  const wroteBinding = writeExclusive(paths.evidenceBinding, value);
  if (!wroteBinding) {
    const existing = readFileSync(paths.evidenceBinding, 'utf8').trim();
    if (existing !== canonicalJson(value)) throw new Error(`managed host run ${runId}: evidence already imported with a different binding`);
  }
  const seal = {
    schemaVersion: 'lattice.managed_review_evidence_binding_seal.v1',
    runId,
    bindingDigest: digestFile(paths.evidenceBinding),
  };
  if (!writeExclusive(paths.evidenceBindingSeal, seal)) {
    const existingSeal = readFileSync(paths.evidenceBindingSeal, 'utf8').trim();
    if (existingSeal !== canonicalJson(seal)) {
      throw new Error(`managed host run ${runId}: evidence binding seal does not match the immutable import`);
    }
  }
}

/** Test/repair helper: validates runtime artifacts without mutating them. */
export function inspectManagedHostRunFiles(root: string, runId: string): {
  mode: number;
  hasCapability: boolean;
  hasPrompt: boolean;
  hasTerminal: boolean;
} {
  const paths = pathsFor(root, runId);
  return {
    mode: statSync(paths.dir).mode & 0o777,
    hasCapability: existsSync(paths.capability),
    hasPrompt: existsSync(paths.prompt),
    hasTerminal: existsSync(paths.terminal),
  };
}

function timestampAgeMs(value: string | null, now: number): number | null {
  if (!value) return null;
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? Math.max(0, now - parsed) : null;
}

/**
 * Read-only operational projection. It deliberately reports heartbeat and
 * provider progress as separate facts: neither a stale heartbeat nor output
 * silence is promoted to a terminal outcome by this scan.
 */
export function scanManagedHostRunRuntime(
  root: string,
  options: { now?: number; retentionMs?: number } = {},
): ManagedHostRunRuntimeScan {
  const runtimeRoot = managedHostRunsRoot(root);
  const now = options.now ?? Date.now();
  const retentionMs = boundedPositiveMs(
    options.retentionMs,
    MANAGED_HOST_RUN_TERMINAL_RETENTION_MS,
    Number.MAX_SAFE_INTEGER,
  );
  const runs: ManagedHostRunRuntimeDiagnostic[] = [];
  if (existsSync(runtimeRoot)) {
    for (const entry of readdirSync(runtimeRoot, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const runId = entry.name;
      try {
        assertRunId(runId);
        const paths = pathsFor(root, runId);
        const run = projectionFor(paths);
        const terminalAt = run.terminal?.terminalAt ?? null;
        const terminalAtMs = terminalAt ? Date.parse(terminalAt) : Number.NaN;
        const retentionEligibleAt = Number.isFinite(terminalAtMs)
          ? new Date(terminalAtMs + retentionMs).toISOString()
          : null;
        const hasUnconsumedOneShotInputs = existsSync(paths.capability)
          || existsSync(paths.prompt)
          || existsSync(paths.environment);
        const workerLiveness = run.terminal
          ? 'not-applicable'
          : run.workerPid === null
            ? 'not-started'
            : pidAlive(run.workerPid)
              ? 'alive'
              : 'dead';
        runs.push({
          runId,
          state: run.state,
          workerLiveness,
          workerHeartbeatAt: run.workerHeartbeatAt,
          workerHeartbeatAgeMs: timestampAgeMs(run.workerHeartbeatAt, now),
          providerProgressMode: run.providerProgressMode,
          lastProviderProgressAt: run.lastProviderProgressAt,
          providerProgressAgeMs: timestampAgeMs(run.lastProviderProgressAt, now),
          deadlineAt: run.deadlineAt,
          deadlineExpired: now >= Date.parse(run.deadlineAt),
          cancelRequestedAt: run.cancelRequestedAt,
          replacementSafe: run.replacementSafe,
          residualProcessGroup: run.terminal?.processCleanup?.residualProcessGroup ?? null,
          terminalAt,
          terminalReason: run.terminal?.reason ?? null,
          retentionEligibleAt,
          retentionExpired: !!retentionEligibleAt && now >= Date.parse(retentionEligibleAt),
          hasUnconsumedOneShotInputs,
          error: null,
        });
      } catch (error) {
        const dir = join(runtimeRoot, runId);
        runs.push({
          runId,
          state: 'corrupt',
          workerLiveness: 'unknown',
          workerHeartbeatAt: null,
          workerHeartbeatAgeMs: null,
          providerProgressMode: 'unknown',
          lastProviderProgressAt: null,
          providerProgressAgeMs: null,
          deadlineAt: null,
          deadlineExpired: null,
          cancelRequestedAt: null,
          replacementSafe: null,
          residualProcessGroup: null,
          terminalAt: null,
          terminalReason: null,
          retentionEligibleAt: null,
          retentionExpired: false,
          hasUnconsumedOneShotInputs: existsSync(join(dir, 'input.cap'))
            || existsSync(join(dir, 'input.prompt'))
            || existsSync(join(dir, 'input.env.json')),
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }
  }
  runs.sort((left, right) => left.runId.localeCompare(right.runId));
  return {
    root: runtimeRoot,
    retentionMs,
    active: runs.filter(run => !['completed', 'failed', 'cancelled', 'timed_out', 'corrupt'].includes(run.state)).length,
    terminal: runs.filter(run => ['completed', 'failed', 'cancelled', 'timed_out'].includes(run.state)).length,
    corrupt: runs.filter(run => run.state === 'corrupt').length,
    eligibleForGc: runs.filter(run => run.retentionExpired && !run.hasUnconsumedOneShotInputs).length,
    runs,
  };
}
/**
 * B-70e9 CHK-001 / CHK-002 / CHK-007: the `host_run` CLI command.
 *
 * A thin wrapper over the core choke point (core/host-run.ts): it validates the
 * args (exactly one of --prompt / --promptFile, canonical host, story/reviewRunId
 * binding), reads the prompt, builds the store-backed story resolver (F-005) and
 * the live passthrough sink (F-006), binds the host execution cwd to the
 * resolved project root (F-011 — the same ctx.root the ledger rows attribute,
 * never the caller's process.cwd()), and delegates to runHostRun. Host output is
 * STREAMED LIVE through the passthrough as it arrives; a usage-summary line is
 * written to stderr; the process exit reflects success vs a host failure / cap
 * refusal.
 *
 * Passthrough routing (F-006):
 *   - text mode -> host stdout chunks go to process.stdout live, host stderr to
 *     process.stderr; the handler does NOT re-print buffered output (no
 *     double-print), so on success it returns an empty string;
 *   - json mode -> ALL host output is routed to process.stderr so process.stdout
 *     stays clean for the single JSON result; the JSON `stdout` field carries only
 *     the bounded usage-parse tail, since the full transcript already streamed to
 *     stderr.
 *
 * Output/exit contract (bounded by the CLI engine, which prints the handler
 * return and forces exit 0 on a normal return):
 *   - text mode, success -> host stdout already streamed live; RETURN '' (nothing
 *     to re-print), usage line to stderr, process exit 0;
 *   - text mode, host failure / cap refusal -> host output already streamed;
 *     usage/refusal line to stderr, THROW a concise error so the process exits
 *     nonzero (the exact host code + refusal reason are in the message);
 *   - json mode -> RETURN the structured result (exitCode, usage, refusal, the
 *     bounded stdout tail, and truncated when the 8 MiB live-output ceiling is
 *     hit are FIELDS); never throws, so machine consumers read exitCode.
 */

import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import type { HandlerContext } from './context.js';
import type { FormatArgs } from './verdict.js';
import {
  type HostRunChunk,
  type HostRunHost,
  type HostRunPassthrough,
  type HostRunResult,
  type HostRunRunner,
  type HostRunStoryResolver,
} from '../core/host-run.js';
import {
  cancelManagedHostRun,
  getManagedHostRunStatus,
  projectManagedHostRunTerminalResult,
  readManagedHostRunOutput,
  readManagedHostRunResult,
  runManagedHostRunWorker,
  submitManagedHostRun,
  type ManagedHostRunProjection,
  type ManagedHostRunWorkerLauncher,
} from '../core/managed-host-run.js';
import { buildManagedReviewerPrompt } from '../core/managed-review-evidence.js';
import { assertCurrentReviewRunForEvidence } from '../core/review-run.js';

export interface HostRunCommandArgs extends FormatArgs {
  host?: string;
  storyId?: string;
  agentType?: string;
  phase?: string;
  prompt?: string;
  promptFile?: string;
  reviewRunId?: string;
  lane?: string;
  timeoutMs?: number;
  deadlineMs?: number;
  detach?: boolean;
  managedReview?: boolean;
}

export interface HostRunStatusCommandArgs extends FormatArgs {
  runId?: string;
  afterGeneration?: number;
  afterSequence?: number;
  waitMs?: number;
}

export interface HostRunCancelCommandArgs extends FormatArgs {
  runId?: string;
  reason?: string;
}

export interface HostRunWorkerCommandArgs {
  runId?: string;
}

interface HostRunOutputStream {
  write(text: string, callback: (error?: Error | null) => void): boolean;
  on(event: 'error', listener: (error: Error) => void): this;
  removeListener(event: 'error', listener: (error: Error) => void): this;
}

/**
 * One late-error guard per physical stream. A capped write can still emit EPIPE
 * after its foreground command returns; keeping the per-run listener would grow
 * without bound when a stream never settles. This shared guard is reference
 * counted by pending writes, so it contains that late event while retaining at
 * most one listener for any stream and disappears once the final write settles.
 */
const lateStreamErrorGuards = new WeakMap<HostRunOutputStream, {
  pending: number;
  listener: (error: Error) => void;
}>();

function retainLateStreamErrorContainment(stream: HostRunOutputStream): () => void {
  let guard = lateStreamErrorGuards.get(stream);
  if (!guard) {
    guard = { pending: 0, listener: () => { /* late EPIPE is intentionally contained */ } };
    lateStreamErrorGuards.set(stream, guard);
    stream.on('error', guard.listener);
  }
  guard.pending += 1;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    const current = lateStreamErrorGuards.get(stream);
    if (!current) return;
    current.pending -= 1;
    if (current.pending <= 0) {
      stream.removeListener('error', current.listener);
      lateStreamErrorGuards.delete(stream);
    }
  };
}

export interface CreateHostRunHandlersOptions {
  /**
   * Test seam: inject a fake host runner. Production uses the async streaming
   * defaultHostRunRunner (core/host-run.ts): child_process.spawn with live
   * chunk passthrough and bounded usage-line retention.
   */
  runner?: HostRunRunner;
  /** Test seam; production launches the hidden detached worker command. */
  launchWorker?: ManagedHostRunWorkerLauncher;
  /** Internal command-smoke seam; production keeps the core 30s maximum. */
  statusWaitCapMs?: number;
  /** Command-smoke seam for deterministic late-settling stream writes. */
  outputStreams?: {
    stdout?: HostRunOutputStream;
    stderr?: HostRunOutputStream;
  };
  /** Command-smoke seam; production preserves the 2s bounded drain cap. */
  streamWriteDrainCapMs?: number;
}

export interface HostRunCommandResult {
  schemaVersion: 'lattice.host_run.v1';
  host: HostRunHost;
  storyId: string | null;
  phase: string;
  agentType: string;
  spawned: boolean;
  blocked: boolean;
  refusalReason: string | null;
  liveRuns: HostRunResult['liveRuns'];
  exitCode: number;
  timedOut: boolean;
  stdout: string;
  stderr: string;
  usage: HostRunResult['usageSummary'];
  /** F-008: non-null when the live output passthrough failed mid-run (run still completed). */
  passthroughError: string | null;
  runId: string;
  managed: true;
  /** True when the managed live-output journal hit the 8 MiB retention ceiling. */
  truncated: boolean;
}

export interface HostRunDetachResult {
  schemaVersion: 'lattice.host_run.v2';
  detached: true;
  run: ManagedHostRunProjection;
}

function normalizeString(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function optionalPositiveInteger(command: string, field: string, value: unknown): number | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== 'number' || !Number.isFinite(value) || !Number.isInteger(value) || value <= 0) {
    throw new Error(`${command}: --${field} must be a finite positive integer`);
  }
  return value;
}

function optionalNonnegativeInteger(
  command: string,
  field: string,
  value: unknown,
  maximum?: number,
): number | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== 'number'
    || !Number.isFinite(value)
    || !Number.isInteger(value)
    || value < 0
    || (maximum !== undefined && value > maximum)) {
    const maximumClause = maximum === undefined ? '' : ` <= ${maximum}`;
    throw new Error(`${command}: --${field} must be a finite nonnegative integer${maximumClause}`);
  }
  return value;
}

function wantsJson(args: FormatArgs | undefined): boolean {
  return args?.json === true || args?.format === 'json';
}

function normalizeHost(raw: string): HostRunHost {
  const value = raw.trim().toLowerCase();
  if (value === 'codex') return 'codex';
  if (value === 'claude' || value === 'claude-code') return 'claude';
  throw new Error(`host_run: unsupported host "${raw}" (expected codex | claude)`);
}

function projectRootHashFor(root: string): string {
  return `sha256:${createHash('sha256').update(root, 'utf8').digest('hex')}`;
}

/** Format the single stderr usage-summary / refusal line. */
function formatUsageLine(result: HostRunResult): string {
  const u = result.usageSummary;
  if (result.blocked) {
    if (result.refusalReason === 'concurrency_cap_exceeded') {
      const list = (result.liveRuns ?? [])
        .map((r) => `  - pid ${r.pid} ${r.host}${r.storyId ? ` story ${r.storyId}` : ''} agentType ${r.agentType} startedAt ${r.startedAt}`)
        .join('\n');
      return `host_run refused: ${u.reason ?? 'concurrency_cap_exceeded'}${list ? `\n${list}` : ''}`;
    }
    return `host_run refused: ${u.reason ?? result.refusalReason ?? 'blocked'}`;
  }
  if (u.recorded === 'disabled') return 'usage ledger disabled (LATTICE_USAGE_LEDGER=0); no rows recorded';
  if (u.recorded === 'provider-reported') {
    const recordId = u.recordId ? ` (recordId ${u.recordId})` : '';
    return `usage recorded: provider=${u.provider ?? 'unknown'} input=${u.input ?? 'null'} cacheRead=${u.cacheRead ?? 'null'} output=${u.output ?? 'null'}${recordId}`;
  }
  if (u.recorded === 'unavailable') {
    return `usage recorded: unavailable (${u.reason ?? 'no usage surface'})`;
  }
  return `usage: ${u.reason ?? 'not recorded'}`;
}

function syntheticManagedResult(run: ManagedHostRunProjection): HostRunResult {
  const exitCode = run.state === 'completed' ? 0 : run.state === 'cancelled' ? 130 : run.state === 'timed_out' ? 124 : 1;
  return {
    host: run.host,
    storyId: run.storyId,
    phase: run.phase,
    agentType: run.agentType,
    spawned: run.workerPid !== null,
    blocked: false,
    refusalReason: null,
    liveRuns: null,
    exitCode,
    timedOut: run.state === 'timed_out',
    timeoutKind: run.state === 'timed_out' ? 'total_timeout' : null,
    terminalReason: run.state === 'completed' ? 'completed' : run.state === 'cancelled' ? 'aborted' : run.state === 'timed_out' ? 'total_timeout' : 'child_error',
    firstOutputMs: null,
    durationMs: Math.max(0, Date.parse(run.terminal?.terminalAt ?? new Date().toISOString()) - Date.parse(run.createdAt)),
    failureKind: run.state === 'timed_out' ? 'timeout' : run.state === 'completed' ? 'none' : 'unknown',
    stdout: '',
    stderr: '',
    usageSummary: {
      recorded: 'none',
      provider: null,
      input: null,
      cacheRead: null,
      output: null,
      recordId: null,
      reason: run.terminal?.reason ?? `managed_${run.state}`,
    },
    passthroughError: null,
    processIdentity: null,
    replacementSafe: run.replacementSafe,
    residualProcessGroup: !run.replacementSafe,
    processCleanup: run.terminal?.processCleanup ?? null,
    finalAssistantResult: null,
    finalAssistantResultCount: 0,
    finalAssistantResultTruncated: false,
  };
}

function projectManagedTerminalResult(run: ManagedHostRunProjection, persisted: HostRunResult | null): HostRunResult {
  const result = persisted ?? syntheticManagedResult(run);
  return run.terminal
    ? projectManagedHostRunTerminalResult(run.terminal.state, result) ?? syntheticManagedResult(run)
    : result;
}

export function createHostRunHandlers(ctx: HandlerContext, options: CreateHostRunHandlersOptions = {}) {
  return {
    async host_run(args: HostRunCommandArgs): Promise<HostRunCommandResult | HostRunDetachResult | string> {
      const host = normalizeHost(normalizeString(args.host));
      const agentType = normalizeString(args.agentType);
      if (!agentType) throw new Error('host_run: --agentType is required');
      const timeoutMs = optionalPositiveInteger('host_run', 'timeoutMs', args.timeoutMs);
      const deadlineMs = optionalPositiveInteger('host_run', 'deadlineMs', args.deadlineMs);
      const storyId = normalizeString(args.storyId) || null;
      const reviewRunId = normalizeString(args.reviewRunId) || null;
      const lane = normalizeString(args.lane) || null;

      // Exactly one of --prompt / --promptFile.
      const hasPrompt = typeof args.prompt === 'string' && args.prompt.length > 0;
      const promptFilePath = normalizeString(args.promptFile);
      const hasPromptFile = promptFilePath.length > 0;
      let promptText: string;
      let formalReviewBinding: {
        headHash: string;
        materialHash: string;
        storyFilesHash: string;
        promptHash: string;
        envelopeId: string | null;
      } | null = null;
      if (args.managedReview === true) {
        if (hasPrompt || hasPromptFile) {
          throw new Error('host_run: --managedReview derives the exact prompt from ReviewRun; do not pass --prompt or --promptFile');
        }
        if (!storyId || !reviewRunId || !lane || agentType !== lane) {
          throw new Error('host_run: --managedReview requires storyId, reviewRunId, lane, and agentType equal to that lane');
        }
        const story = ctx.store.readStory(storyId);
        const reviewRun = assertCurrentReviewRunForEvidence(ctx.store, story, ctx.root, lane, reviewRunId);
        const storyFilesHash = reviewRun.storyFilesHash ?? reviewRun.workspaceBinding?.storyFilesHash ?? '';
        if (!storyFilesHash) throw new Error('host_run: --managedReview requires a ReviewRun with storyFilesHash binding');
        promptText = buildManagedReviewerPrompt(reviewRun.workspaceBinding?.metadataRoot ?? ctx.root, reviewRun);
        formalReviewBinding = {
          headHash: reviewRun.headHash,
          materialHash: reviewRun.materialHash,
          storyFilesHash,
          promptHash: reviewRun.promptHash,
          envelopeId: reviewRun.envelopeId ?? null,
        };
      } else if (hasPrompt === hasPromptFile) {
        throw new Error('host_run: provide exactly one of --prompt or --promptFile (or use --managedReview with an exact ReviewRun)');
      } else if (hasPromptFile) {
        try {
          promptText = readFileSync(promptFilePath, 'utf8');
        } catch (err) {
          throw new Error(`host_run: cannot read --promptFile "${promptFilePath}": ${err instanceof Error ? err.message : String(err)}`);
        }
      } else {
        promptText = args.prompt as string;
      }
      if (promptText.length === 0) {
        throw new Error('host_run: prompt is empty; refuse pre-spawn');
      }

      // Defense in depth (core enforces this too): a reviewRunId must belong to
      // --storyId so a ledger row cannot silently mis-join across stories.
      if (reviewRunId && storyId && !reviewRunId.startsWith(`${storyId}:`)) {
        throw new Error(
          `host_run: reviewRunId "${reviewRunId}" does not belong to story "${storyId}" ` +
          `(a reviewRunId must be "<storyId>:..."); refuse pre-spawn`,
        );
      }
      const json = wantsJson(args);

      // F-005: resolve story phase + existence through the CONFIGURED store, so a
      // project that configures storyDir is honored (the core stays path-free). An
      // explicit --phase never reaches this (the core skips the store entirely).
      const resolveStory: HostRunStoryResolver = (id: string) => {
        try {
          const story = ctx.store.readStory(id);
          const p = typeof story.phase === 'string' && story.phase.length > 0 ? story.phase : null;
          return { phase: p };
        } catch {
          return null; // unknown story per the configured store
        }
      };

      const explicitPhase = normalizeString(args.phase);
      let phase = explicitPhase || 'adhoc';
      if (!explicitPhase && storyId) {
        const story = resolveStory(storyId);
        if (!story) throw new Error(`host_run: unknown story "${storyId}"; refuse pre-spawn`);
        phase = story.phase || 'adhoc';
      }
      const injectedLauncher: ManagedHostRunWorkerLauncher | undefined = options.runner
        ? async request => {
          void runManagedHostRunWorker(request, { runner: options.runner, env: process.env })
            .catch(() => { /* worker persists its own terminal error where possible */ });
          return { pid: process.pid };
        }
        : undefined;
      const submitted = await submitManagedHostRun(
        {
          host,
          storyId,
          agentType,
          phase,
          promptText,
          reviewRunId,
          lane,
          timeoutMs,
          deadlineMs: deadlineMs ?? timeoutMs,
          cwd: ctx.root,
          root: ctx.root,
          projectRootHash: projectRootHashFor(ctx.root),
          ...(formalReviewBinding ? { profile: 'managed_reviewer', reviewBinding: formalReviewBinding } : {}),
        },
        { launchWorker: options.launchWorker ?? injectedLauncher },
      );
      // Publish the durable identity before either detach returns or foreground
      // attach begins. If the caller disappears while attached, a replacement
      // controller can recover the same worker-owned run through host_run_status
      // instead of launching a duplicate provider.
      ctx.log?.(
        `[host_run] submitted runId=${submitted.runId} state=${submitted.state} `
        + `deadlineAt=${submitted.deadlineAt} attach=${args.detach === true ? 'detached' : 'foreground'}`,
      );
      if (args.detach === true) {
        return { schemaVersion: 'lattice.host_run.v2', detached: true, run: submitted };
      }

      // F-006 / F-008 / F-020: live passthrough. text mode routes host
      // stdout->stdout / stderr->stderr; json mode routes EVERYTHING to stderr so
      // stdout stays clean for the JSON result.
      // F-008: a SYNCHRONOUS write failure is normalized and thrown to the CORE
      // guard, which flips its passthrough-broken flag: delivery stops, the run
      // still completes, and result.passthroughError surfaces the failure honestly.
      // F-020: a real EPIPE (the downstream pipe closed) usually surfaces NOT as a
      // synchronous throw but as an ASYNCHRONOUS 'error' event on process.stdout /
      // process.stderr, which the try/catch below cannot see. The 'error' listeners
      // attached for the duration of the run (below) record the first such failure
      // into `asyncStreamError`; the sink checks it and throws-through so the SAME
      // core passthrough-broken flag flips (delivery stops instead of hammering a
      // dead pipe), and the handler also merges it into the surfaced
      // passthroughError as a backstop for an error that lands after the last chunk.
      let asyncStreamError: string | null = null;
      const stdout = options.outputStreams?.stdout ?? process.stdout;
      const stderr = options.outputStreams?.stderr ?? process.stderr;
      // F-020 / F-024: track a broken STDOUT and STDERR specifically. Any chunk or
      // diagnostic write issued to a stream we already KNOW is broken would queue an
      // async EPIPE 'error' that can fire AFTER the per-call listener is removed
      // (zero listeners -> process crash). We skip those writes instead — honest
      // degradation, since passthroughError already records the failure.
      let stdoutBroken = false;
      let stderrBroken = false;

      // F-020: contain ASYNC stream 'error' events (real EPIPE) for the DURATION of
      // the run. Node terminates the process only when a stream has ZERO 'error'
      // listeners, so simply attaching ours is sufficient containment: we swallow
      // the error and record the first message. Hygiene: exactly our two named
      // listeners are added below and removed with removeListener in the finally
      // — never removeAllListeners, since other code may hold its own listeners on
      // these shared streams. F-024: a write error surfaced through a write CALLBACK
      // folds into the SAME state, so a late EPIPE reported via callback and one
      // reported via the 'error' event are handled identically.
      const recordStreamError = (streamName: 'stdout' | 'stderr') => (err: unknown): void => {
        if (streamName === 'stderr') stderrBroken = true;
        else stdoutBroken = true;
        if (asyncStreamError === null) {
          const message = err instanceof Error ? err.message : String(err);
          asyncStreamError = `host_run passthrough ${streamName} stream error: ${message}`;
        }
      };
      const onStdoutError = recordStreamError('stdout');
      const onStderrError = recordStreamError('stderr');

      // F-024: outstanding-write accounting for the live passthrough AND the final
      // diagnostics, WITHOUT serializing throughput. Every write below is issued as
      // write(text, cb) and is NOT awaited per-chunk; the callback decrements a
      // shared pending counter. drainPending() — awaited by the finally BEFORE the
      // error listeners are removed — resolves once every in-flight write has
      // settled, so a late EPIPE from the FINAL chunk(s) fires while our named
      // 'error' listeners are still attached. This closes the residual window that
      // F-020/F-023 left on fire-and-forget live passthrough writes.
      let pendingWrites = 0;
